1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	
50	const BASE_PREMIUMS = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	} as const satisfies Record<string, number>;
58	
59	type InsurableItemType = keyof typeof BASE_PREMIUMS;
60	
61	const isInsurable = (type: string): type is InsurableItemType =>
62	  type in BASE_PREMIUMS;
63	
64	/**
65	 * The single gate every per-type lookup passes through: an item the MHPCO does
66	 * not insure is rejected here rather than yielding an undefined rate later.
67	 */
68	const insurableTypeOf = (item: Item): InsurableItemType => {
69	  if (!isInsurable(item.type)) {
70	    throw new Error(`The MHPCO does not insure a ${item.type}`);
71	  }
72	  return item.type;
73	};
74	
75	const basePremiumOf = (item: Item): number =>
76	  BASE_PREMIUMS[insurableTypeOf(item)];
77	
78	/** Premiums are rounded up — in MHPCO's favour. */
79	const roundPremium = (amount: number): number => Math.ceil(amount);
80	
81	const COMPONENT_BLOCK_SIZE = 3;
82	const COMPONENT_BLOCK_PREMIUM = 60;
83	
84	/** Items of a single type, kept together so the block rule can be applied. */
85	type SameTypeGroup = Item[];
86	
87	const groupByType = (items: Item[]): SameTypeGroup[] => {
88	  const groups = new Map<string, SameTypeGroup>();
89	  for (const item of items) {
90	    const group = groups.get(item.type) ?? [];
91	    group.push(item);
92	    groups.set(item.type, group);
93	  }
94	  return [...groups.values()];
95	};
96	
97	const sumBasePremiums = (group: SameTypeGroup): number =>
98	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
99	
100	/**
101	 * Exactly three alike items form a building block priced at a flat premium;
102	 * any other count is priced per item.
103	 */
104	const blockAwareBasePremium = (group: SameTypeGroup): number =>
105	  group.length === COMPONENT_BLOCK_SIZE
106	    ? COMPONENT_BLOCK_PREMIUM
107	    : sumBasePremiums(group);
108	
109	const policyBasePremiumFor = (items: Item[]): number =>
110	  groupByType(items).reduce(
111	    (sum, group) => sum + blockAwareBasePremium(group),
112	    0,
113	  );
114	
115	const HIGH_ENCHANTMENT_LEVEL = 5;
116	
117	const isCursed = (item: Item): boolean => item.cursed === true;
118	const isHighlyEnchanted = (item: Item): boolean =>
119	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
120	
121	/**
122	 * An item-specific surcharge: when the item triggers the clause, it is charged
123	 * a rate of that item's own base premium — never of the whole policy's.
124	 */
125	interface ItemSurcharge {
126	  appliesTo: (item: Item) => boolean;
127	  rate: number;
128	}
129	
130	const ITEM_SURCHARGES: ItemSurcharge[] = [
131	  { appliesTo: isCursed, rate: 0.5 },
132	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
133	];
134	
135	/** Every clause the item triggers stacks, each on that item's base premium. */
136	const surchargeRateFor = (item: Item): number =>
137	  ITEM_SURCHARGES.reduce(
138	    (rate, surcharge) =>
139	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
140	    0,
141	  );
142	
143	const itemSurchargesFor = (items: Item[]): number =>
144	  items.reduce(
145	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
146	    0,
147	  );
148	
149	/** Every quote is an initial assessment, so this surcharge always applies. */
150	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
151	const LOYALTY_DISCOUNT_RATE = -0.2;
152	const LOYALTY_YEARS = 2;
153	
154	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
155	
156	/** What the MHPCO knows about the customer when pricing a particular quote. */
157	interface QuoteContext {
158	  customer: Customer;
159	  previousContracts: number;
160	}
161	
162	const isLoyal = ({ customer }: QuoteContext): boolean =>
163	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
164	const isFollowUpContract = ({ previousContracts }: QuoteContext): boolean =>
165	  previousContracts > 0;
166	
167	/**
168	 * A policy-wide modifier: when the customer triggers the clause, the whole
169	 * policy's base premium is adjusted by that rate — never a single item's.
170	 * A negative rate is a discount.
171	 */
172	interface PolicyModifier {
173	  appliesTo: (context: QuoteContext) => boolean;
174	  rate: number;
175	}
176	
177	/** Conditional clauses, on top of the surcharge every quote already carries. */
178	const POLICY_MODIFIERS: PolicyModifier[] = [
179	  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
180	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_DISCOUNT_RATE },
181	];
182	
183	/** Every clause the customer triggers stacks on the policy base premium. */
184	const policyModifierRateFor = (context: QuoteContext): number =>
185	  POLICY_MODIFIERS.reduce(
186	    (rate, modifier) =>
187	      modifier.appliesTo(context) ? rate + modifier.rate : rate,
188	    FIRST_INSURANCE_SURCHARGE_RATE,
189	  );
190	
191	const quotePremium = (items: Item[], context: QuoteContext): number => {
192	  const policyBasePremium = policyBasePremiumFor(items);
193	  return roundPremium(
194	    policyBasePremium +
195	      policyBasePremium * policyModifierRateFor(context) +
196	      itemSurchargesFor(items) +
197	      PROCESSING_FEE,
198	  );
199	};
200	
201	const INSURANCE_VALUES = {
202	  sword: 1000,
203	  amulet: 600,
204	  staff: 800,
205	  potion: 400,
206	  rune: 250,
207	  moonstone: 250,
208	} as const satisfies Record<InsurableItemType, number>;
209	
210	const insuranceValueOf = (item: Item): number =>
211	  INSURANCE_VALUES[insurableTypeOf(item)];
212	
213	const DEDUCTIBLE = 100;
214	const CAP_MULTIPLIER = 2;
215	
216	/** Payouts are rounded down — in MHPCO's favour. */
217	const roundPayout = (amount: number): number => Math.floor(amount);
218	
219	/** A policy created by a quote step, tracked so later claims can draw on it. */
220	interface Policy {
221	  items: Item[];
222	  remainingCap: number;
223	}
224	
225	const openPolicy = (items: Item[]): Policy => ({
226	  items,
227	  remainingCap:
228	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + insuranceValueOf(item), 0),
229	});
230	
231	const FULL_REIMBURSEMENT_RATE = 1;
232	
233	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
234	const REDUCED_REIMBURSEMENT_RATE = 0.5;
235	
236	/** Damage to a very highly enchanted item is only half reimbursed. */
237	const reimbursementRateFor = (item: Item): number =>
238	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL
239	    ? REDUCED_REIMBURSEMENT_RATE
240	    : FULL_REIMBURSEMENT_RATE;
241	
242	/** The deductible can absorb a small damage entirely, but never turns it into a debt. */
243	const afterDeductible = (amount: number): number =>
244	  Math.max(0, amount - DEDUCTIBLE);
245	
246	const payoutForDamage = (damage: Damage, item: Item): number =>
247	  afterDeductible(damage.amount * reimbursementRateFor(item));
248	
249	/**
250	 * Settling draws the payout from the policy's cap, so it yields the policy as
251	 * it stands afterwards rather than modifying the one passed in — the caller
252	 * decides whether to keep the drawn-down policy.
253	 */
254	interface Settlement {
255	  result: StepResult;
256	  policy: Policy;
257	}
258	
259	/** A damage entry together with the insured item it will be settled against. */
260	interface ClaimedDamage {
261	  damage: Damage;
262	  item: Item;
263	}
264	
265	/**
266	 * Each damage entry is settled against a distinct insured item, so claiming
267	 * for more items of a type than the policy covers is rejected outright — as is
268	 * a damage that could never have happened. Both are checked before any money is
269	 * computed, so an unsettleable claim is rejected whole rather than in part.
270	 */
271	const matchDamagesToInsuredItems = (
272	  policy: Policy,
273	  damages: Damage[],
274	): ClaimedDamage[] => {
275	  const unclaimed = [...policy.items];
276	  return damages.map((damage) => {
277	    if (damage.amount < 0) {
278	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
279	    }
280	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
281	    if (index === -1) {
282	      throw new Error(`${damage.itemType} is not insured by this policy`);
283	    }
284	    return { damage, item: unclaimed.splice(index, 1)[0] };
285	  });
286	};
287	
288	const settleClaim = (policy: Policy, incident: Incident): Settlement => {
289	  const claimedPayout = matchDamagesToInsuredItems(
290	    policy,
291	    incident.damages,
292	  ).reduce((sum, { damage, item }) => sum + payoutForDamage(damage, item), 0);
293	  const payout = roundPayout(Math.min(claimedPayout, policy.remainingCap));
294	  const remainingCap = policy.remainingCap - payout;
295	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
296	};
297	
298	/** A claim may only draw on a policy that an earlier quote step actually opened. */
299	const policyOpenedBy = (
300	  policies: Map<number, Policy>,
301	  step: number,
302	): Policy => {
303	  const policy = policies.get(step);
304	  if (policy === undefined) {
305	    throw new Error(`No policy created by step ${step}`);
306	  }
307	  return policy;
308	};
309	
310	export const runScenario = (scenario: Scenario): ScenarioResult => {
311	  const policies = new Map<number, Policy>();
312	  let previousContracts = 0;
313	
314	  const results = scenario.steps.map((step, index) => {
315	    if (step.op === "quote") {
316	      const context = { customer: scenario.customer, previousContracts };
317	      previousContracts += 1;
318	      policies.set(index, openPolicy(step.items));
319	      return { premium: quotePremium(step.items, context) };
320	    }
321	
322	    const settlement = settleClaim(
323	      policyOpenedBy(policies, step.policy),
324	      step.incident,
325	    );
326	    policies.set(step.policy, settlement.policy);
327	    return settlement.result;
328	  });
329	
330	  return { results };
331	};
