11	const main = async (): Promise<void> => {
12	  const input = await readStdin();
13	  try {
14	    const scenario = JSON.parse(input) as Scenario;
15	    process.stdout.write(JSON.stringify(runScenario(scenario)));
16	  } catch (error) {
17	    process.stderr.write(`${(error as Error).message}\n`);
18	    process.exitCode = 1;
19	  }
20	};
